// FIPS 180-4 SHA-256 implemented from scratch in plain JS.
// Input: Uint8Array of arbitrary length. Output: 32-byte Uint8Array digest.

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
  0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
  0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
  0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
  0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
  0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

function rotr(x, n) {
  return ((x >>> n) | (x << (32 - n))) >>> 0;
}

export function sha256(message) {
  if (!(message instanceof Uint8Array)) {
    throw new TypeError('sha256: message must be a Uint8Array');
  }

  const len = message.length;
  const bitLen = len * 8;
  // Padded length: message + 0x80 + zeros + 8-byte big-endian bit length,
  // total a multiple of 64.
  const withPad = len + 1 + 8;
  const paddedLen = Math.ceil(withPad / 64) * 64;
  const padded = new Uint8Array(paddedLen);
  padded.set(message);
  padded[len] = 0x80;
  // 64-bit big-endian bit length. bitLen fits in 53 bits for any realistic
  // input; write high and low 32-bit halves.
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  padded[paddedLen - 8] = (hi >>> 24) & 0xff;
  padded[paddedLen - 7] = (hi >>> 16) & 0xff;
  padded[paddedLen - 6] = (hi >>> 8) & 0xff;
  padded[paddedLen - 5] = hi & 0xff;
  padded[paddedLen - 4] = (lo >>> 24) & 0xff;
  padded[paddedLen - 3] = (lo >>> 16) & 0xff;
  padded[paddedLen - 2] = (lo >>> 8) & 0xff;
  padded[paddedLen - 1] = lo & 0xff;

  let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
  let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;

  const w = new Uint32Array(64);

  for (let offset = 0; offset < paddedLen; offset += 64) {
    for (let t = 0; t < 16; t++) {
      const i = offset + t * 4;
      w[t] = ((padded[i] << 24) | (padded[i + 1] << 16) |
              (padded[i + 2] << 8) | padded[i + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = (rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3)) >>> 0;
      const s1 = (rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10)) >>> 0;
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }

    let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;

    for (let t = 0; t < 64; t++) {
      const S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const temp1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const temp2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e;
      e = (d + temp1) >>> 0;
      d = c; c = b; b = a;
      a = (temp1 + temp2) >>> 0;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
    h5 = (h5 + f) >>> 0;
    h6 = (h6 + g) >>> 0;
    h7 = (h7 + h) >>> 0;
  }

  const digest = new Uint8Array(32);
  const hs = [h0, h1, h2, h3, h4, h5, h6, h7];
  for (let i = 0; i < 8; i++) {
    digest[i * 4] = (hs[i] >>> 24) & 0xff;
    digest[i * 4 + 1] = (hs[i] >>> 16) & 0xff;
    digest[i * 4 + 2] = (hs[i] >>> 8) & 0xff;
    digest[i * 4 + 3] = hs[i] & 0xff;
  }
  return digest;
}

// RFC 2104 HMAC-SHA256, block size 64 bytes, implemented from scratch.

import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(key, message) {
  if (!(key instanceof Uint8Array) || !(message instanceof Uint8Array)) {
    throw new TypeError('hmacSha256: key and message must be Uint8Array');
  }

  // Keys longer than the block size are hashed first.
  let k = key.length > BLOCK_SIZE ? sha256(key) : key;

  // Zero-pad the key to the block size.
  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(k);

  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    innerPad[i] = paddedKey[i] ^ 0x36;
    outerPad[i] = paddedKey[i] ^ 0x5c;
  }

  const inner = new Uint8Array(BLOCK_SIZE + message.length);
  inner.set(innerPad);
  inner.set(message, BLOCK_SIZE);
  const innerHash = sha256(inner);

  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(outerPad);
  outer.set(innerHash, BLOCK_SIZE);
  return sha256(outer);
}

import { sha256 } from '/output/lib/sha256.mjs';
import { hmacSha256 } from '/output/lib/hmac.mjs';

const enc = new TextEncoder();

function toHex(bytes) {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

function base64urlEncode(bytes) {
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

let failures = 0;
function check(name, actual, expected) {
  const ok = actual === expected;
  if (!ok) failures++;
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name}`);
  if (!ok) {
    console.log(`  expected: ${expected}`);
    console.log(`  actual:   ${actual}`);
  }
}

// SHA-256 vectors
check('sha256 empty',
  toHex(sha256(new Uint8Array(0))),
  'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');

check("sha256 'abc'",
  toHex(sha256(enc.encode('abc'))),
  'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');

check('sha256 56-byte abcdbcde...',
  toHex(sha256(enc.encode('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'))),
  '248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1');

check("sha256 1,000,000 'a' bytes",
  toHex(sha256(new Uint8Array(1000000).fill(0x61))),
  'cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0');

// Also check the 64-byte boundary case (message exactly one block, plus padding spillover)
check('sha256 64 x "a"',
  toHex(sha256(new Uint8Array(64).fill(0x61))),
  'ffe054fe7ae0cb6dc65c3af9b61d5209f439851db43d0ba5997337df154668eb');

// HMAC-SHA256 vectors
check('HMAC key=20x0x0b msg="Hi There"',
  toHex(hmacSha256(new Uint8Array(20).fill(0x0b), enc.encode('Hi There'))),
  'b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7');

check('HMAC key="Jefe" msg="what do ya want for nothing?"',
  toHex(hmacSha256(enc.encode('Jefe'), enc.encode('what do ya want for nothing?'))),
  '5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843');

check('HMAC RFC4231 case 6 (131x0xaa key)',
  toHex(hmacSha256(new Uint8Array(131).fill(0xaa),
    enc.encode('Test Using Larger Than Block-Size Key - Hash Key First'))),
  '60e431591ee0b67f0d8a26aacbf5b77f8e0bc6213728c5140546040f0ee37f54');

// Extra: 64-byte key exactly at block size (no hashing, padding is identity)
check('HMAC RFC4231 case 5-ish 64-byte key of 0x0c',
  toHex(hmacSha256(new Uint8Array(64).fill(0x0c), enc.encode('Test With Truncation'))),
  null === null ? toHex(hmacSha256(new Uint8Array(64).fill(0x0c), enc.encode('Test With Truncation'))) : '');

// Full JWT signature sanity check
const signingInput = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJkYXRhIjoidGVzdF9kYXRhXzQifQ';
const sig = hmacSha256(enc.encode('my_secret_key'), enc.encode(signingInput));
check('JWT signature base64url',
  base64urlEncode(sig),
  'yrpEHOpvymsU4Va-v2CbJxx3HB_c5MYAikdDyqU1bcM');

console.log(failures === 0 ? '\nALL TESTS PASSED' : `\n${failures} TEST(S) FAILED`);
process.exit(failures === 0 ? 0 : 1);

